package org.nonfood.oilplants.web;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import org.nonfood.oilplants.dao.*;import java.io.*;
@WebServlet("/admin/users") public class AdminUsersServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{WebSupport.requireAdmin(r);r.setAttribute("users",new UserDao().allUsers());WebSupport.view(r,s,"admin/users");}catch(Exception e){WebSupport.error(r,s,e,"用户列表暂时不可用。");}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{WebSupport.requireAdmin(r);long id=Long.parseLong(r.getParameter("id"));boolean enabled="true".equals(r.getParameter("enabled"));new UserDao().setEnabled(id,enabled);new AuditDao().log(WebSupport.user(r).getId(),"USER_STATUS","user",id,enabled?"enabled":"disabled",r.getRemoteAddr());r.getSession().setAttribute("flash","用户状态已更新。");s.sendRedirect(r.getContextPath()+"/admin/users");}catch(Exception e){WebSupport.error(r,s,e,"更新用户状态失败。");}}}
